module div_16bit (
    input wire [15:0] A,
    input wire [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    always @(*) begin
        if (B == 0) begin
            result = 0;
            odd = A;
        end else begin
            result = A / B;
            odd = A % B;
        end
    end

endmodule

module multi_8bit (
    input [7:0] A,
    input [7:0] B,
    output reg [15:0] product
);

    integer i;

    always @(*) begin
        product = 16'b0;  

        for (i = 0; i < 8; i = i + 1) begin

            if (B[i] == 1'b1) begin
                product = product + (A << i);
            end
        end
    end

endmodule

module adder_16bit (
    input [15:0] a,
    input [15:0] b,
    input Cin,
    output reg [15:0] y,
    output reg Co
);

    wire [7:0] sum_low;
    wire Cout_low;

    adder_8bit low_adder (
        .a(a[7:0]),
        .b(b[7:0]),
        .cin(Cin),
        .sum(sum_low),
        .co(Cout_low)
    );

    wire [7:0] sum_high;
    wire Cout_high;

    adder_8bit high_adder (
        .a(a[15:8]),
        .b(b[15:8]),
        .cin(Cout_low),
        .sum(sum_high),
        .co(Cout_high)
    );

    assign y = {sum_high, sum_low};
    assign Co = Cout_high;

endmodule

