module add1 (
    input a,
    input b,
    input Cin,
    output y,
    output Co
);
    assign y = ((~a) & (~b) & Cin | (~a) & b & (~Cin) | a & (~b) & (~Cin) | (a & b & Cin));
    assign Co = ((~a & b & Cin) | (a & ~b & Cin) | (a & b & ~Cin) | (a & b & Cin));

endmodule

module width_8to16 (
    input 				   clk,
    input 				   rst_n,
    input				      valid_in,
    input	   [7:0]		   data_in,
    output	reg			valid_out,
    output   reg [15:0]	data_out
);

    reg [7:0] data_lock;
    reg flag;
    reg [15:0] data_out_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out_reg <= 16'b0;
            data_lock <= 8'b0;
            flag <= 1'b0;
            valid_out <= 1'b0;
        end else begin
            if (valid_in && !flag) begin
                data_lock <= data_in;
                flag <= 1'b1;
            end else if (valid_in && flag) begin
                data_out_reg <= {data_lock, data_in};
                flag <= 1'b0;
                valid_out <= 1'b1;
            end
        end
    end

    assign data_out = data_out_reg;

endmodule

module multi_16bit (
    input clk,
    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output reg [31:0] yout,
    output reg done
);

    reg [4:0] i;
    reg [15:0] areg;
    reg [15:0] breg;
    reg [31:0] yout_r;
    reg done_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            i <= 5'd0;
            areg <= 16'd0;
            breg <= 16'd0;
            yout_r <= 32'd0;
            done_r <= 1'b0;
        end else begin
            if (start) begin
                if (i == 5'd0) begin
                    areg <= ain;
                    breg <= bin;
                end else if (i < 5'd17) begin
                    if (areg[i-1]) begin
                        yout_r <= yout_r + (breg << (i-1));
                    end
                end
                i <= i + 5'd1;
            end else begin
                i <= 5'd0;
            end
            if (i == 5'd16) begin
                done_r <= 1'b1;
            end else begin
                done_r <= 1'b0;
            end
        end
    end

    assign yout = yout_r;
    assign done = done_r;

endmodule

module counter_12 (
    input rst_n,
    input clk,
    input valid_count,
    output reg [3:0] out
);
    parameter MAX_COUNT = 4'd11;

    reg [3:0] count_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count_reg <= 4'b0000;
        end else if (valid_count) begin
            if (count_reg == MAX_COUNT) begin
                count_reg <= 4'b0000;
            end else begin
                count_reg <= count_reg + 1;
            end
        end
    end

    assign out = count_reg;
endmodule

module calendar (
    input CLK,
    input RST,
    output reg [5:0] Hours,
    output reg [5:0] Mins,
    output reg [5:0] Secs
);

    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            Secs <= 6'd0;
            Mins <= 6'd0;
            Hours <= 6'd0;
        end else begin
            if (Secs == 6'd59) begin
                Secs <= 6'd0;
                if (Mins == 6'd59) begin
                    Mins <= 6'd0;
                    if (Hours == 6'd23) begin
                        Hours <= 6'd0;
                    end else begin
                        Hours <= Hours + 1;
                    end
                end else begin
                    Mins <= Mins + 1;
                end
            end else begin
                Secs <= Secs + 1;
            end
        end
    end

endmodule

