module cla_16bit(
    input [15:0] a,
    input [15:0] b,
    input cin,
    output [15:0] sum,
    output cout,
    output p_group,
    output g_group
);
    wire [3:0] p_4bit; 
    wire [3:0] g_4bit; 
    wire [3:0] c_16bit; 


    cla_4bit cla_block0(
        .a(a[3:0]),
        .b(b[3:0]),
        .cin(cin),
        .sum(sum[3:0]),
        .cout(c_16bit[0]),
        .p_group(p_4bit[0]),
        .g_group(g_4bit[0])
    );


    cla_4bit cla_block1(
        .a(a[7:4]),
        .b(b[7:4]),
        .cin(c_16bit[0]),
        .sum(sum[7:4]),
        .cout(c_16bit[1]),
        .p_group(p_4bit[1]),
        .g_group(g_4bit[1])
    );


    cla_4bit cla_block2(
        .a(a[11:8]),
        .b(b[11:8]),
        .cin(c_16bit[1]),
        .sum(sum[11:8]),
        .cout(c_16bit[2]),
        .p_group(p_4bit[2]),
        .g_group(g_4bit[2])
    );


    cla_4bit cla_block3(
        .a(a[15:12]),
        .b(b[15:12]),
        .cin(c_16bit[2]),
        .sum(sum[15:12]),
        .cout(c_16bit[3]),
        .p_group(p_4bit[3]),
        .g_group(g_4bit[3])
    );


    assign p_group = p_4bit[0] & p_4bit[1] & p_4bit[2] & p_4bit[3];
    assign g_group = g_4bit[3] | 
                    (g_4bit[2] & p_4bit[3]) | 
                    (g_4bit[1] & p_4bit[3] & p_4bit[2]) | 
                    (g_4bit[0] & p_4bit[3] & p_4bit[2] & p_4bit[1]);


    assign cout = c_16bit[3];
endmodule

module cla_4bit(
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout,
    output p_group,
    output g_group
);
    wire [3:0] p; 
    wire [3:0] g; 
    wire [4:0] c; 


    assign p = a ^ b;
    assign g = a & b;


    assign c[0] = cin;
    assign c[1] = g[0] | (p[0] & c[0]);
    assign c[2] = g[1] | (p[1] & c[1]);
    assign c[3] = g[2] | (p[2] & c[2]);
    assign c[4] = g[3] | (p[3] & c[3]);


    assign sum = p ^ {c[3:0]};


    assign p_group = p[0] & p[1] & p[2] & p[3];
    assign g_group = g[3] | (g[2] & p[3]) | (g[1] & p[3] & p[2]) | (g[0] & p[3] & p[2] & p[1]);


    assign cout = c[4];
endmodule

module edge_detect (
    input clk,
    input rst_n,
    input a,
    output reg rise,
    output reg down
);

    reg a_prev;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            a_prev <= 0;
            rise <= 0;
            down <= 0;
        end else begin
            a_prev <= a;
            if (a_prev == 0 && a == 1) begin
                rise <= 1;
                down <= 0;
            end else if (a_prev == 1 && a == 0) begin
                rise <= 0;
                down <= 1;
            end else begin
                rise <= 0;
                down <= 0;
            end
        end
    end

endmodule

module adder_8bit (
    input [7:0] a,
    b,
    input cin,
    output [7:0] sum,
    output cout
);

    wire [7:0] carry;

    assign {carry[0], sum[0]} = a[0] + b[0] + cin;
    assign {carry[1], sum[1]} = a[1] + b[1] + carry[0];
    assign {carry[2], sum[2]} = a[2] + b[2] + carry[1];
    assign {carry[3], sum[3]} = a[3] + b[3] + carry[2];
    assign {carry[4], sum[4]} = a[4] + b[4] + carry[3];
    assign {carry[5], sum[5]} = a[5] + b[5] + carry[4];
    assign {carry[6], sum[6]} = a[6] + b[6] + carry[5];
    assign {carry[7], sum[7]} = a[7] + b[7] + carry[6];

    assign cout = carry[7];

endmodule

module full_adder (input a, b, cin, output sum, cout);
    assign {cout, sum} = a + b + cin;
endmodule

module signal_generator (
    input clk,
    input rst_n,
    output reg [4:0] wave
);

    parameter IDLE = 2'b00;
    parameter INCREMENT = 2'b01;

    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wave <= 5'b00000;
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (wave == 5'b11111) begin
                        state <= INCREMENT;
                    end else begin
                        wave <= wave + 1;
                    end
                end
                INCREMENT: begin
                    if (wave == 5'b00000) begin
                        state <= IDLE;
                    end else begin
                        wave <= wave - 1;
                    end
                end
                default: begin
                    wave <= 5'b00000;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

module accu (
    input               clk,
    input               rst_n,
    input       [7:0]   data_in,
    input               valid_in,
    output  reg         valid_out,
    output  reg [9:0]   data_out
);

    parameter ACCUMULATE_COUNT = 4;

    reg [1:0] count;
    reg [9:0] accumulated_sum;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 2'b00;
            accumulated_sum <= 10'b0000000000;
            valid_out <= 1'b0;
        end else begin
            if (valid_in && count < ACCUMULATE_COUNT) begin
                accumulated_sum <= accumulated_sum + data_in;
                count <= count + 1'b1;
            end
            if (count == ACCUMULATE_COUNT) begin
                valid_out <= 1'b1;
            end else begin
                valid_out <= 1'b0;
            end
        end
    end

endmodule

module right_shifter (
    input clk,
    output reg [7:0] q,
    input d
);

    initial begin
        q = 8'b0;
    end

    always @(posedge clk) begin
        q <= (q >> 1);
        q[7] <= d;
    end

endmodule

module serial2parallel (
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0]dout_parallel,
    output reg dout_valid
);

reg [3:0] cnt;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        dout_parallel <= 8'b0;
        dout_valid <= 1'b0;
        cnt <= 4'b0;
    end else begin
        if (din_valid) begin
            dout_parallel[cnt] <= din_serial;
            cnt <= cnt + 1;
            if (cnt == 4'b1111) begin
                dout_valid <= 1'b1;
            end else begin
                dout_valid <= 1'b0;
            end
        end else begin
            if (cnt == 4'b1111) begin
                dout_valid <= 1'b0;
            end
        end
    end
end

endmodule

module RAM #(
    parameter WIDTH=6,
    parameter DEPTH=8
) (
    input clk,
    input rst_n,
    input write_en,
    input [$clog2(DEPTH)-1:0]write_addr,
    input [WIDTH-1:0]write_data,
    input read_en,
    input [$clog2(DEPTH)-1:0]read_addr,
    output reg [WIDTH-1:0]read_data
);

reg [WIDTH-1:0] mem [0:DEPTH-1];

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        read_data <= {WIDTH{1'b0}};
        foreach (mem[i]) mem[i] <= {WIDTH{1'b0}};
    end else begin
        if (write_en)
            mem[write_addr] <= write_data;
        if (read_en)
            read_data <= mem[read_addr];
    end
end

endmodule

module freq_div (
    input CLK_in,
    output reg CLK_50,
    output reg CLK_10,
    output reg CLK_1,
    input RST
);

    reg [3:0] cnt_10;
    reg [6:0] cnt_100;

    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            CLK_50 <= 0;
            CLK_10 <= 0;
            CLK_1 <= 0;
            cnt_10 <= 0;
            cnt_100 <= 0;
        end else begin
            CLK_50 <= ~CLK_50;

            cnt_10 <= cnt_10 + 1;
            if (cnt_10 == 9) begin
                CLK_10 <= ~CLK_10;
                cnt_10 <= 0;
            end

            cnt_100 <= cnt_100 + 1;
            if (cnt_100 == 99) begin
                CLK_1 <= ~CLK_1;
                cnt_100 <= 0;
            end
        end
    end

endmodule

module synchronizer (
    input 				clk_a,
    input 				clk_b,
    input 				arstn,
    input				brstn,
    input		[3:0]	data_in,
    input               data_en,
    output reg  [3:0] 	dataout
);

    reg [3:0] data_reg;
    reg en_data_reg;
    reg en_clap_one;
    reg en_clap_two;

    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) begin
            data_reg <= 4'b0;
        end else begin
            if (data_en) begin
                data_reg <= data_in;
            end
        end
    end

    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) begin
            en_data_reg <= 1'b0;
        end else begin
            en_data_reg <= data_en;
        end
    end

    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) begin
            en_clap_one <= 1'b0;
            en_clap_two <= 1'b0;
        end else begin
            en_clap_one <= en_data_reg;
            en_clap_two <= en_clap_one;
        end
    end

    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) begin
            dataout <= 4'b0;
        end else begin
            if (en_clap_two) begin
                dataout <= data_reg;
            end
        end
    end

endmodule

module parallel2serial (
    input wire clk,
    input wire rst_n,
    input wire [3:0]d,
    output reg valid_out,
    output reg dout
);

    reg [1:0] cnt;
    reg [3:0] data;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 2'b00;
            data <= 4'b0000;
            valid_out <= 1'b0;
        end else begin
            if (cnt == 2'b11) begin
                data <= d;
                cnt <= 2'b00;
                valid_out <= 1'b1;
            end else begin
                cnt <= cnt + 1'b1;
                valid_out <= 1'b0;
                data <= {data[2:0], data[3]};
            end
        end
    end

    assign dout = data[3];

endmodule

module div_8bit (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output reg [15:0] result
);

reg [7:0] abs_dividend, abs_divisor, remainder, quotient;
reg [7:0] sr;
reg [2:0] cnt, start_cnt;
reg neg_divisor;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        res_valid <= 0;
        result <= 0;
        cnt <= 0;
        start_cnt <= 0;
        sr <= 0;
        remainder <= 0;
        quotient <= 0;
        neg_divisor <= 0;
    end else begin
        if (opn_valid && !res_valid) begin
            abs_dividend <= (sign && dividend[7]) ? ~dividend + 1 : dividend;
            abs_divisor <= (sign && divisor[7]) ? ~divisor + 1 : divisor;
            sr <= {abs_dividend, 1'b0};
            neg_divisor <= ~abs_divisor + 1;
            cnt <= 1;
            start_cnt <= 1;
            remainder <= 0;
            quotient <= 0;
        end else if (start_cnt) begin
            if (cnt == 8) begin
                cnt <= 0;
                start_cnt <= 0;
                result <= {remainder, quotient};
            end else begin
                cnt <= cnt + 1;
                if (sr >= neg_divisor) begin
                    sr <= sr - neg_divisor;
                    quotient <= quotient | (1 << (7 - cnt));
                end
                sr <= {sr[6:0], 1'b0};
            end
        end
        if (cnt == 8) begin
            res_valid <= 1;
        end else if (res_valid && res_ready) begin
            res_valid <= 0;
        end
    end
end

endmodule

module adder_pipe_64bit #(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
) (
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output reg [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] sum_reg;
reg [DATA_WIDTH:0] sum_next;
reg [STG_WIDTH-1:0] stage_en;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum_reg <= {DATA_WIDTH{1'b0}};
        stage_en <= {STG_WIDTH{1'b0}};
        o_en <= 1'b0;
    end else begin
        if (i_en) begin
            sum_next <= adda + addb;
            stage_en <= {STG_WIDTH{1'b1}};
        end else begin
            sum_next <= sum_reg;
            stage_en <= {STG_WIDTH{1'b0}};
        end
        sum_reg <= sum_next;
        o_en <= |stage_en;
    end
end

assign result = sum_reg;

endmodule

module pulse_detect #(
    parameter s0 = 2'b00,
    parameter s1 = 2'b01,
    parameter s2 = 2'b10,
    parameter s3 = 2'b11
) (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    parameter IDLE = 2'b00;
    parameter RISING = 2'b01;
    parameter FALLING = 2'b10;
    parameter PULSE_END = 2'b11;

    reg [1:0] state;
    reg next_state;

    always @(*) begin
        case (state)
            IDLE: begin
                if (data_in == 1'b1) next_state = RISING;
                else next_state = IDLE;
            end
            RISING: begin
                if (data_in == 1'b0) next_state = FALLING;
                else next_state = RISING;
            end
            FALLING: begin
                if (data_in == 1'b1) next_state = PULSE_END;
                else next_state = IDLE;
            end
            PULSE_END: begin
                if (data_in == 1'b0) next_state = IDLE;
                else next_state = PULSE_END;
            end
            default: next_state = IDLE;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            data_out <= 0;
        end else begin
            state <= next_state;
            data_out <= (state == PULSE_END);
        end
    end

endmodule

module multi_pipe_4bit #(
    parameter size = 4,
    parameter N = 2 * size
) (
    input 						clk,
    input 						rst_n,
    input	[size-1:0]			mul_a,
    input	[size-1:0]			mul_b,
    output	reg	[size*2-1:0]	mul_out
);

reg [size*2-1:0] sum_tmp1;
reg [size*2-1:0] sum_tmp2;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum_tmp1 <= 0;
        sum_tmp2 <= 0;
    end else begin
        sum_tmp1 <= (mul_b[0] ? mul_a : 0) + (mul_b[1] ? mul_a << 1 : 0) +
