module multi_pipe_8bit #(
    parameter size = 8
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    input mul_en_in,
    output reg mul_en_out,
    output reg [size*2-1:0] mul_out
);

reg [7:0] mul_a_reg;
reg [7:0] mul_b_reg;
reg [7:0] temp [0:7];
reg [15:0] sum [0:3];

reg [2:0] mul_en_out_reg;
reg [15:0] mul_out_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_a_reg <= 8'b0;
        mul_b_reg <= 8'b0;
        mul_en_out_reg <= 3'b0;
        mul_out_reg <= 16'b0;
        for (integer i = 0; i < 4; i++) begin
            sum[i] <= 16'b0;
        end
    end else begin
        if (mul_en_in) begin
            mul_a_reg <= mul_a;
            mul_b_reg <= mul_b;
            mul_en_out_reg <= {mul_en_out_reg[1:0], mul_en_in};
        end

        for (integer i = 0; i < 4; i++) begin
            temp[i*2] <= mul_a_reg & (mul_b_reg >>> (i*2));
            temp[i*2 + 1] <= mul_a_reg & (mul_b_reg >>> ((i*2) + 1));
        end

        sum[0] <= temp[0] + temp[1];
        sum[1] <= temp[2] + temp[3];
        sum[2] <= temp[4] + temp[5];
        sum[3] <= temp[6] + temp[7];

        mul_out_reg <= sum[0] + sum[1] + sum[2] + sum[3];
    end
end

assign mul_en_out = mul_en_out_reg[2];
assign mul_out = mul_out_reg;

endmodule

module alu #(
    parameter ADD = 6'b100000,
    parameter ADDU = 6'b100001,
    parameter SUB = 6'b100010,
    parameter SUBU = 6'b100011,
    parameter AND = 6'b100100,
    parameter OR = 6'b100101,
    parameter XOR = 6'b100110,
    parameter NOR = 6'b100111,
    parameter SLT = 6'b101010,
    parameter SLTU = 6'b101011,
    parameter SLL = 6'b000000,
    parameter SRL = 6'b000010,
    parameter SRA = 6'b000011,
    parameter SLLV = 6'b000100,
    parameter SRLV = 6'b000110,
    parameter SRAV = 6'b000111,
    parameter LUI = 6'b001111
) (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output reg zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output reg flag
);

    wire [31:0] res;
    assign res = a + b;
    assign zero = (res == 32'b0);
    assign negative = (res[31]);
    assign overflow = ((a[31] == b[31]) && (a[31] != res[31]));
    assign flag = (aluc == SLT || aluc == SLTU) ? (res[31]) : 1'bz;

    always @(*) begin
        case (aluc)
            ADD: r = a + b;
            ADDU: r = a + b;
            SUB: r = a - b;
            SUBU: r = a - b;
            AND: r = a & b;
            OR: r = a | b;
            XOR: r = a ^ b;
            NOR: r = ~(a | b);
            SLT: r = {31'b0, a[31] < b[31]};
            SLTU: r = {31'b0, a < b};
            SLL: r = a << b[4:0];
            SRL: r = a >> b[4:0];
            SRA: r = $signed(a) >>> b[4:0];
            SLLV: r = a << (b & 31);
            SRLV: r = a >> (b & 31);
            SRAV: r = $signed(a) >>> (b & 31);
            LUI: r = {b, 16'b0};
            default: r = 32'b0;
        endcase
    end

endmodule

module traffic_light #(
    parameter idle = 2'd0,
    parameter s1_red = 2'd1,
    parameter s2_yellow = 2'd2,
    parameter s3_green = 2'd3
) (
    input rst_n,
    input clk,
    input pass_request,
    output wire[7:0]clock,
    output reg red,
    output reg yellow,
    output reg green
);

reg [7:0] cnt;
reg [1:0] state;
reg p_red, p_yellow, p_green;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
        cnt <= 8'd0;
        red <= 1'b0;
        yellow <= 1'b0;
        green <= 1'b0;
    end else begin
        case (state)
            idle: begin
                state <= s1_red;
                cnt <= 8'd0;
            end
            s1_red: begin
                red <= 1'b1;
                if (cnt < 8'd59) begin
                    cnt <= cnt + 1;
                end else begin
                    state <= s3_green;
                    cnt <= 8'd0;
                end
            end
            s2_yellow: begin
                yellow <= 1'b1;
                if (cnt < 8'd4) begin
                    cnt <= cnt + 1;
                end else begin
                    state <= s1_red;
                    cnt <= 8'd0;
                end
            end
            s3_green: begin
                green <= 1'b1;
                if (cnt < 8'd9) begin
                    cnt <= cnt + 1;
                end else begin
                    state <= s2_yellow;
                    cnt <= 8'd0;
                end
            end
        endcase
    end
end

assign clock = cnt;

endmodule

module asyn_fifo #(
    parameter	WIDTH = 8,
    parameter 	DEPTH = 16,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output wire				wfull,
    output wire				rempty,
    output wire [WIDTH-1:0]	rdata
);

    reg [WIDTH-1:0] ram [0:DEPTH-1];
    reg [$clog2(DEPTH)-1:0] wp, rp;
    reg [$clog2(DEPTH)-1:0] wp_gray, rp_gray;

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wp <= 0;
        end else if (winc && !wfull) begin
            wp <= wp + 1;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rp <= 0;
        end else if (rinc && !rempty) begin
            rp <= rp + 1;
        end
    end

    assign wp_gray = wp ^ (wp >> 1);
    assign rp_gray = rp ^ (rp >> 1);

    assign wfull = (wp_gray == {~rp_gray[ADDR_WIDTH-1], rp_gray[ADDR_WIDTH-2:0]});
    assign rempty = (wp_gray == rp_gray);

    assign rdata = ram[rp];

endmodule

module dual_port_RAM #(parameter DEPTH = 16,  parameter WIDTH = 8)
(
	 input wclk	,
	 input wenc	,
	 input [$clog2(DEPTH)-1:0] waddr  ,
	 input [WIDTH-1:0] wdata ,
	 input rclk	,
	 input renc	,
	 input [$clog2(DEPTH)-1:0] raddr ,
	 output reg [WIDTH-1:0] rdata 		
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
	if(wenc)
		RAM_MEM[waddr] <= wdata;
end 

always @(posedge rclk) begin
	if(renc)
		rdata <= RAM_MEM[raddr];
end 

endmodule
